(function () {
'use strict';
const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const isTouch = window.matchMedia('(hover: none)').matches;
let lenis = null;
function initLenis() {
if (prefersReduced || typeof Lenis === 'undefined') return null;
const instance = new Lenis({
duration: 1.3,
easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
smoothWheel: true,
wheelMultiplier: 1.1,
touchMultiplier: 1.8,
infinite: false
});
if (window.ScrollTrigger) {
instance.on('scroll', ScrollTrigger.update);
gsap.ticker.add((time) => instance.raf(time * 1000));
gsap.ticker.lagSmoothing(500, 33);
} else {
function raf(time) {
instance.raf(time);
requestAnimationFrame(raf);
}
requestAnimationFrame(raf);
}
return instance;
}
function initAnchors() {
document.querySelectorAll('a[href^="#"]').forEach((link) => {
link.addEventListener('click', (e) => {
const id = link.getAttribute('href');
if (!id || id === '#') return;
const target = document.querySelector(id);
if (!target) return;
e.preventDefault();
if (lenis) lenis.scrollTo(target, { offset: -80, duration: 1.6 });
else target.scrollIntoView({ behavior: 'smooth', block: 'start' });
closeNav();
});
});
}
function initChrome() {
const hdr = document.querySelector('.hdr');
const progress = document.querySelector('.progress');
function onScroll() {
const y = window.scrollY || window.pageYOffset;
const stuck = y > 40;
if (hdr) hdr.classList.toggle('is-stuck', stuck);
document.documentElement.classList.toggle('hdr-stuck', stuck);
if (progress) {
const max = document.documentElement.scrollHeight - window.innerHeight;
const pct = max > 0 ? (y / max) * 100 : 0;
progress.style.width = pct + '%';
}
}
window.addEventListener('scroll', onScroll, { passive: true });
onScroll();
}
function closeNav() {
const nav = document.querySelector('.nav');
const toggle = document.querySelector('.nav-toggle');
const wasOpen = nav && nav.classList.contains('is-open');
if (nav) nav.classList.remove('is-open');
document.body.classList.remove('nav-open');
if (toggle) toggle.setAttribute('aria-expanded', 'false');
if (wasOpen && toggle) toggle.focus();
if (lenis) lenis.start();
}
function openNav() {
const nav = document.querySelector('.nav');
const toggle = document.querySelector('.nav-toggle');
if (!nav) return;
nav.classList.add('is-open');
document.body.classList.add('nav-open');
if (toggle) toggle.setAttribute('aria-expanded', 'true');
if (lenis) lenis.stop();
}
function initNav() {
const toggle = document.querySelector('.nav-toggle');
const closeBtn = document.querySelector('.nav-close');
const nav = document.querySelector('.nav');
if (!toggle || !nav) return;
toggle.addEventListener('click', () => {
nav.classList.contains('is-open') ? closeNav() : openNav();
});
if (closeBtn) closeBtn.addEventListener('click', closeNav);
document.addEventListener('keydown', (e) => {
if (e.key === 'Escape' && nav.classList.contains('is-open')) closeNav();
});
nav.addEventListener('keydown', (e) => {
if (e.key !== 'Tab' || !nav.classList.contains('is-open')) return;
const focusables = nav.querySelectorAll(
'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])'
);
if (!focusables.length) return;
const first = focusables[0];
const last = focusables[focusables.length - 1];
if (e.shiftKey && document.activeElement === first) {
e.preventDefault();
last.focus();
} else if (!e.shiftKey && document.activeElement === last) {
e.preventDefault();
first.focus();
}
});
window.addEventListener('resize', () => {
if (window.innerWidth > 760 && nav.classList.contains('is-open')) closeNav();
}, { passive: true });
}
function initFaq() {
document.querySelectorAll('.faq-item').forEach((item) => {
const btn = item.querySelector('.faq-q');
const panel = item.querySelector('.faq-a');
if (!btn || !panel) return;
btn.addEventListener('click', () => {
const isOpen = item.classList.contains('is-open');
const group = item.parentElement;
if (group) {
group.querySelectorAll('.faq-item.is-open').forEach((other) => {
if (other === item) return;
other.classList.remove('is-open');
const op = other.querySelector('.faq-a');
const ob = other.querySelector('.faq-q');
if (op) op.style.height = '0px';
if (ob) ob.setAttribute('aria-expanded', 'false');
});
}
item.classList.toggle('is-open', !isOpen);
btn.setAttribute('aria-expanded', String(!isOpen));
panel.style.height = isOpen ? '0px' : panel.scrollHeight + 'px';
});
});
window.addEventListener('resize', () => {
document.querySelectorAll('.faq-item.is-open .faq-a').forEach((p) => {
p.style.height = p.scrollHeight + 'px';
});
}, { passive: true });
}
const PRODUCTS = {
'omfad-1':   { name: 'On My Feet All Day',        qty: '1 unit', price: 399 },
'nea-1':     { name: 'Normal Everyday Activity',  qty: '1 unit', price: 399 },
'bundle-2':  { name: '2 Unit Package',            qty: '2 unit', price: 699 }
};
let selected = 'bundle-2';
let quantity = 1;
const MAX_QTY = 10;
function renderSummary() {
const p = PRODUCTS[selected];
const perPack = parseInt(p.qty, 10) || 1;
const totalUnits = perPack * quantity;
const totalPrice = p.price * quantity;
const el = {
name:  document.getElementById('sum-name'),
qty:   document.getElementById('sum-qty'),
total: document.getElementById('sum-total'),
cta:   document.getElementById('cta-total-bb'),
qv:    document.getElementById('qty-value'),
minus: document.getElementById('qty-minus'),
plus:  document.getElementById('qty-plus')
};
if (el.name)  el.name.textContent  = p.name;
if (el.qty)   el.qty.textContent   = quantity > 1
? quantity + ' × ' + p.qty + ' = ' + totalUnits + ' unit'
: p.qty;
if (el.total) el.total.textContent = 'RM' + totalPrice;
if (el.cta)   el.cta.textContent   = 'RM' + totalPrice;
if (el.qv)    el.qv.textContent    = String(quantity);
if (el.minus) el.minus.disabled    = quantity <= 1;
if (el.plus)  el.plus.disabled     = quantity >= MAX_QTY;
}
function initQty() {
const minus = document.getElementById('qty-minus');
const plus  = document.getElementById('qty-plus');
if (minus) minus.addEventListener('click', () => {
if (quantity > 1) { quantity--; renderSummary(); }
});
if (plus) plus.addEventListener('click', () => {
if (quantity < MAX_QTY) { quantity++; renderSummary(); }
});
}
function initForm() {
document.querySelectorAll('[data-product]').forEach((opt) => {
opt.addEventListener('click', () => {
document.querySelectorAll('[data-product]').forEach((o) => o.classList.remove('is-picked'));
opt.classList.add('is-picked');
selected = opt.getAttribute('data-product');
quantity = 1;
renderSummary();
});
});
renderSummary();
initQty();
const form = document.getElementById('order-form');
if (!form) return;
form.addEventListener('submit', (e) => {
e.preventDefault();
const fd = new FormData(form);
const p = PRODUCTS[selected];
const perPack = parseInt(p.qty, 10) || 1;
const totalUnits = perPack * quantity;
const totalPrice = p.price * quantity;
const no = 'ISL-' + Math.floor(100000 + Math.random() * 900000);
const set = (id, val) => {
const n = document.getElementById(id);
if (n) n.textContent = val;
};
set('cf-no', no);
set('cf-name', fd.get('name') || '—');
set('cf-phone', fd.get('phone') || '—');
set('cf-product', p.name + ' — ' + totalUnits + ' unit'
+ (quantity > 1 ? ' (' + quantity + ' × ' + p.qty + ')' : ''));
set('cf-total', 'RM' + totalPrice);
const checkout = document.getElementById('view-checkout');
const done = document.getElementById('view-confirm');
if (checkout) checkout.hidden = true;
if (done) done.hidden = false;
if (lenis) lenis.scrollTo(0, { immediate: false, duration: 0.9 });
else window.scrollTo({ top: 0, behavior: 'smooth' });
if (window.ScrollTrigger) ScrollTrigger.refresh();
});
}
function initGsap() {
const revealHero = () => {
document.querySelectorAll('.hero .line-inner').forEach((el) => {
el.style.transform = 'none';
});
document.querySelectorAll('.hero-sub, .hero-actions, .hero-meta, .hero-visual')
.forEach((el) => { el.style.opacity = '1'; });
};
if (typeof gsap === 'undefined') { revealHero(); return; }
if (window.ScrollTrigger) gsap.registerPlugin(ScrollTrigger);
const reduced = prefersReduced;
if (!reduced) {
gsap.to('.hero .line-inner', {
y: 0,
duration: 1.25,
ease: 'expo.out',
stagger: 0.09,
delay: 0.15
});
gsap.from('.hero-sub, .hero-actions, .hero-meta', {
y: 26, opacity: 0, duration: 1.1, ease: 'expo.out', stagger: 0.1, delay: 0.55
});
gsap.from('.hero-visual', {
y: 60, opacity: 0, scale: 0.96, duration: 1.5, ease: 'expo.out', delay: 0.35
});
gsap.from('.hero .scroll-hint', { opacity: 0, duration: 1, delay: 1.4 });
setTimeout(revealHero, 4000);
setTimeout(() => {
document.querySelectorAll('[data-reveal]').forEach((el) => {
if (getComputedStyle(el).opacity === '0') {
el.style.opacity = '1';
el.style.transform = 'none';
}
});
}, 6000);
} else {
gsap.set('.hero .line-inner', { y: 0 });
}
if (!window.ScrollTrigger) return;
if (!reduced) {
document.querySelectorAll('[data-reveal]').forEach((el) => {
gsap.to(el, {
opacity: 1,
y: 0,
duration: 1.05,
ease: 'expo.out',
scrollTrigger: { trigger: el, start: 'top 88%', once: true }
});
});
['[data-reveal-group]'].forEach((sel) => {
document.querySelectorAll(sel).forEach((group) => {
const kids = group.querySelectorAll('[data-reveal]');
if (!kids.length) return;
gsap.to(kids, {
opacity: 1, y: 0, duration: 1, ease: 'expo.out', stagger: 0.09,
scrollTrigger: { trigger: group, start: 'top 82%', once: true }
});
});
});
} else {
gsap.set('[data-reveal]', { opacity: 1, y: 0 });
}
if (!reduced && !isTouch) {
document.querySelectorAll('.split-visual-film').forEach((film) => {
gsap.fromTo(film,
{ yPercent: -7 },
{
yPercent: 7,
ease: 'none',
scrollTrigger: {
trigger: film.closest('.split-visual'),
start: 'top bottom',
end: 'bottom top',
scrub: 1
}
}
);
});
}
if (!reduced) {
const heroInner = document.querySelector('.hero-inner');
if (heroInner) {
gsap.to(heroInner, {
y: -70,
opacity: 0.45,
ease: 'none',
scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: 0.3 }
});
}
const heroVisual = document.querySelector('.hero-visual');
if (heroVisual) {
gsap.to(heroVisual, {
y: -140,
ease: 'none',
scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: 0.5 }
});
}
const heroBg = document.querySelector('.hero-bg-img');
if (heroBg) {
gsap.fromTo(heroBg,
{ scale: 1.15 },
{
scale: 1.0,
ease: 'none',
scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: 0.5 }
}
);
}
const heroOverlay = document.querySelector('.hero-bg-overlay');
if (heroOverlay) {
gsap.to(heroOverlay, {
opacity: 0.4,
ease: 'none',
scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: 0.5 }
});
}
}
if (!reduced) {
gsap.from('.process-row', {
opacity: 0,
y: 30,
duration: 0.9,
ease: 'expo.out',
stagger: 0.08,
scrollTrigger: { trigger: '.process-list', start: 'top 82%', once: true }
});
}
if (!reduced) {
document.querySelectorAll('.section-head h2').forEach((h) => {
gsap.from(h, {
opacity: 0, y: 34, duration: 1.1, ease: 'expo.out',
scrollTrigger: { trigger: h, start: 'top 88%', once: true }
});
});
}
ScrollTrigger.refresh();
}
function initFilms() {
const films = Array.from(document.querySelectorAll('.split-visual-film'));
if (!films.length) return;
if (prefersReduced) {
films.forEach((v) => {
v.removeAttribute('autoplay');
v.pause();
v.addEventListener('play', () => v.pause());
});
return;
}
films.forEach((v) => {
let wanted = false;
const play = () => {
if (!wanted || !v.paused) return;
const p = v.play();
if (p && p.catch) p.catch(() => {});
};
if (!('IntersectionObserver' in window)) { wanted = true; play(); return; }
const io = new IntersectionObserver((entries) => {
entries.forEach((e) => {
wanted = e.isIntersecting;
if (wanted) play();
else v.pause();
});
}, { threshold: 0.25 });
io.observe(v);
v.addEventListener('canplay', play);
});
}
function initLoader() {
const loader = document.getElementById('loader');
const bar = document.getElementById('loader-bar');
const pct = document.getElementById('loader-pct');
if (!loader) {
document.body.classList.remove('is-loading');
return;
}
let p = 0;
let done = false;
const timer = setInterval(() => {
const step = p < 70 ? 9 : p < 90 ? 3 : 1.2;
p = Math.min(p + step, 100);
if (bar) bar.style.width = p + '%';
if (pct) pct.textContent = String(Math.round(p)).padStart(3, '0') + '%';
if (p >= 100 && !done) {
done = true;
clearInterval(timer);
setTimeout(finish, 260);
}
}, 55);
function finish() {
loader.classList.add('is-done');
document.body.classList.remove('is-loading');
if (lenis) lenis.start();
if (window.ScrollTrigger) ScrollTrigger.refresh();
setTimeout(() => loader.remove(), 800);
}
setTimeout(() => {
if (!done) { done = true; clearInterval(timer); finish(); }
}, 4000);
}
function boot() {
if (prefersReduced) document.documentElement.classList.add('no-motion');
if (typeof gsap !== 'undefined') {
document.documentElement.classList.add('js-reveal');
}
lenis = initLenis();
if (lenis) lenis.stop();
initChrome();
initNav();
initAnchors();
initFaq();
initForm();
initFilms();
initGsap();
initLoader();
const y = document.getElementById('year');
if (y) y.textContent = new Date().getFullYear();
}
window.addEventListener('error', () => {
document.body.classList.remove('is-loading');
const loader = document.getElementById('loader');
if (loader) loader.style.display = 'none';
document.querySelectorAll('[data-reveal]').forEach((el) => {
el.style.opacity = '1';
el.style.transform = 'none';
});
});
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', boot);
} else {
boot();
}
})();